import pandas as pd

def laporan_dedup(df, subset):
    b = df.copy()
    for k in subset:
        b[k] = b[k].str.strip().str.lower()
    sesudah = len(b.drop_duplicates(subset))
    return {'sebelum': len(df), 'sesudah': sesudah, 'dibuang': len(df) - sesudah}
